function setup() {
	createCanvas(500, 500);
	// noLoop() removed for animation
	noFill();
	strokeWeight(2);
}

function draw() {
	background("#fffbe6");

	let margin = 50;
	let n = 24;
	let s = (width-2*margin)/n;

	square(margin, margin, width-2*margin);
	for (let i = 0; i < n; i++) {
		let x = margin + i*s;
		for (let j = 0; j < n; j++) {
			let y = margin + j*s;
			//square(x, y, s);
			makeTile(x, y, s, 400);
		}
	}

	strokeWeight(1.5);
	drawingContext.setLineDash([s/3, s/2]);
	let kStep = 6;
	for (let k = kStep; k < n; k += kStep) {
		let z = margin + k*s;
		line(margin, z, width-margin, z);
		line(z, margin, z, height-margin);
	}

	noStroke();
	let palette = ["#2b67af", "#f589a3", "#ef562f", "#f9d531"];
	fill(random(palette));
	let i = ~~random(kStep-1) + kStep*~~random(n/kStep);
	var x = margin + i*s;
	let j = ~~random(kStep-1) + kStep*~~random(n/kStep);
	var y = margin + j*s;
	circle(x+s, y+s, s/2);
}

let valFunc = (x, y, density) => (floor(noise(x/density, y/density)*30)%2);

function makeTile(x, y, s, density) {
	let a = valFunc(x, y, density);
	let b = valFunc(x+s, y, density);
	let c = valFunc(x, y+s, density);
	let d = valFunc(x+s, y+s, density);
	let e = valFunc(x+s/2, y+s/2, density);

	if (a) {
		if (b) {
			if (c) {
				if (d) {
