				} else {
					// a && b && c && !d
					arc(x+s, y+s, s, s, PI, 3*PI/2);
				}
			} else {
				if (d) {
					// a && b && !c && d
					arc(x, y+s, s, s, 3*PI/2, TAU);
				} else {
					// a && b && !c && !d
					line(x, y+s/2, x+s, y+s/2);
				}
			}
		} else {
			if (c) {
				if (d) {
					// a && !b && c && d
					arc(x+s, y, s, s, PI/2, PI);
				} else {
					// a && !b && c && !d
					line(x+s/2, y, x+s/2, y+s);
				}
			} else {
				if (d) {
					// a && !b && !c && d
					if (e) {
						arc(x+s, y, s, s, PI/2, PI);
						arc(x, y+s, s, s, 3*PI/2, TAU);
					} else {
						arc(x, y, s, s, 0, PI/2);
						arc(x+s, y+s, s, s, PI, 3*PI/2);
					}
				} else {
					// a && !b && !c && !d
					arc(x, y, s, s, 0, PI/2);
				}
			}
		}
	} else {
		if (b) {
			if (c) {
				if (d) {
					// !a && b && c && d
					arc(x, y, s, s, 0, PI/2);
				} else {
					// !a && b && c && !d
					if (e) {
						arc(x, y, s, s, 0, PI/2);
						arc(x+s, y+s, s, s, PI, 3*PI/2);
					} else {
						arc(x+s, y, s, s, PI/2, PI);
						arc(x, y+s, s, s, 3*PI/2, TAU);
					}
				}
			} else {
				if (d) {
					// !a && b && !c && d
					line(x+s/2, y, x+s/2, y+s);
				} else {
					// !a && b && !c && !d
					arc(x+s, y, s, s, PI/2, PI);
				}
			}
		} else {
			if (c) {
				if (d) {
					// !a && !b && c && d
					line(x, y+s/2, x+s, y+s/2);
				} else {
					// !a && !b && c && !d
					arc(x, y+s, s, s, 3*PI/2, TAU);
				}
			} else {
				if (d) {
